import json
rows=[json.loads(l) for l in open('history/results/samples.jsonl')]
def stats(cand):
    out={}
    for r in rows:
        if r['candidate']!=cand: continue
        t=r['task']; s=out.setdefault(t,{'n':0,'corr':0,'f1':[],'prec':[],'rec':[],'tool':{},'wrong':[]})
        s['n']+=1
        if r['was_correct']: s['corr']+=1
        else: s['wrong'].append(r)
        m=r.get('metric') or {}
        s['f1'].append(m.get('f1') or 0); s['prec'].append(m.get('precision') or 0); s['rec'].append(m.get('recall') or 0)
        for tc in r.get('tool_calls') or []: s['tool'][tc]=s['tool'].get(tc,0)+1
    for t,s in out.items():
        print(cand,t,'acc=%.3f'%(s['corr']/s['n']),'f1=%.3f'%(sum(s['f1'])/len(s['f1'])),'P=%.3f'%(sum(s['prec'])/len(s['prec'])),'R=%.3f'%(sum(s['rec'])/len(s['rec'])),'tools=',s['tool'])
for c in ['baseline','reference_profile','atomic_reference_units','considered_unit_audit','precedent_audit']: stats(c)
"

