import json,re
rows=[json.loads(l) for l in open('/workspace/history/results/samples.jsonl')]
def parse(t):
    m=re.search(r'\[罪名\](.*?)(?:<eoa>|$)',t)
    if m: t=m.group(1).strip()
    t=re.sub(r'<eoa>.*','',t).strip()
    for sep in [';','；',',','，','、']:
        if sep in t: return set(p.strip() for p in t.split(sep) if p.strip())
    return {t} if t else set()
for cand in ['considered_unit_audit','precedent_audit']:
    cats={'exact':0,'subset':0,'superset':0,'partial':0,'disjoint':0}
    nunit=[]
    for r in rows:
        if r['candidate']!=cand or r['task']!='LawBench': continue
        p=parse(r['prediction']); t=parse(r['target'])
        nunit.append(len(t))
        if p==t: cats['exact']+=1
        elif p<t: cats['subset']+=1
        elif p>t: cats['superset']+=1
        elif p&t: cats['partial']+=1
        else: cats['disjoint']+=1
    print(cand, cats, 'target units dist', {k:nunit.count(k) for k in sorted(set(nunit))})
    # predicted unit count dist
EOF

