base='/workspace/history/candidates/precedent_audit/LawBench/conversations'
def parse(t):
    m=re.search(r'\[罪名\](.*?)(?:<eoa>|$)',t or '')
    if m: t=m.group(1).strip()
    t=re.sub(r'<eoa>.*','',t or '').strip()
    for sep in [';','；',',','，','、']:
        if sep in t: return set(p.strip() for p in t.split(sep) if p.strip())
    return {t} if t else set()
miss_named=0; miss_unnamed=0; wrong=0; correct=0; multi_gold_correct=0; multi_gold=0
excl=[]
for ex in sorted(os.listdir(base)):
    for s in sorted(os.listdir(os.path.join(base,ex))):
        d=json.load(open(os.path.join(base,ex,s)))
        if 'target' not in d: continue
        gold=parse(d['target']); pred=parse(d['prediction'])
        cons=set()
        for m in d['messages']:
            for tc in m.get('tool_calls') or []:
