        act = act.strip().strip("。.!?！？:：\"'()（）[]【】 ")
        unit = unit.strip().strip("。.!?！？:：\"'()（）[]【】 ")
        ruled_out = unit.strip().lower() in RULED_OUT
        if ruled_out:
            unit = ""
        if not unit:
            named = [label for label, _ in self.label_pairs if label in entry]
            named.sort(key=len, reverse=True)
            unit = named[0] if named else ""
